/* .xlsx test files as base64 (no Node file APIs in tests):
   RESAVED = a Research workbook re-saved by openpyxl (deflate, as Excel saves);
   SHARED = a hand-made sheet with shared strings, rich text and a non-default sheet path. */
const b64 = (s: string) => Uint8Array.from(atob(s), c => c.charCodeAt(0));
export const RESAVED = b64('');
export const SHARED = b64('');
